Implementation:

```ts
const STATUS_VALUES = ['running', 'done', 'failed', 'skipped'] as const
const VERDICTS = ['aligned', 'partial', 'empty', 'divergent'] as const

function parseJson(body: string): Record<string, unknown> | undefined {
  try {
    const p = JSON.parse(body)
    return p && typeof p === 'object' && !Array.isArray(p) ? (p as Record<string, unknown>) : undefined
  } catch {
    return undefined
  }
}

async function updateStatus(jobId, input) {
  try {
    const res = await client.callTool({ name: 'update_job_status', arguments: { job_id: jobId, ...input } })
    const body = text(res)
    if (res.isError) return { ok: false, message: body }
    const p = parseJson(body)
    if (!p) return { ok: true, message: body }
    const out: StatusOutcome = { ok: true }
    if ((STATUS_VALUES as readonly string[]).includes(p.status as string)) out.status = p.status as StatusOutcome['status']
    if (typeof p.branch === 'string' || p.branch === null) out.branch = p.branch
    if (typeof p.pushed_at === 'string' || p.pushed_at === null) out.pushedAt = p.pushed_at
    if (typeof p.error === 'string' || p.error === null) out.error = p.error
    return out
  } catch (err) {
    return { ok: false, message: message(err) }
  }
}
```

