async verifyTaskAgainstPlan(taskId, worktreePath) {
  try {
    const res = await client.callTool({ name: 'verify_task_against_plan', arguments: { task_id: taskId, worktree_path: worktreePath } })
    const body = text(res)
    if (res.isError) return { ok: false, message: body }
    const p = parseJson(body)
    if (!p || p.ok === false) return { ok: false, message: body }
    const result = typeof p.result === 'string' ? (p.result.toLowerCase() as string) : undefined
    return { ok: true, ...(VERDICTS.includes(result) ? { result: result as 'aligned' } : {}) }
  } catch (err) {
    return { ok: false, message: message(err) }
  }
}
