      } catch (err) {
        return { ok: false, message: message(err) }
      }
      if (res.isError) return { ok: false, message: text(res) }
      // The reply is the real outcome: status, branch, pushed_at, error (spec §4.1).
      const body = text(res)
      let parsed: unknown
      try {
        parsed = JSON.parse(body)
      } catch {
        return { ok: true, message: body }
      }
      const p = parsed as { status?: unknown; branch?: unknown; pushed_at?: unknown; error?: unknown }
      const outcome: StatusOutcome = { ok: true }
      if (typeof p?.status === 'string' && ['running', 'done', 'failed', 'skipped'].includes(p.status)) outcome.status = p.status
      if (typeof p?.branch === 'string' || p?.branch === null) outcome.branch = p.branch
      if (typeof p?.pushed_at === 'string' || p?.pushed_at === null) outcome.pushedAt = p.pushed_at
      if (typeof p?.error === 'string' || p?.error === null) outcome.error = p.error
      return outcome
    },

    async updateTaskStatus(taskId, status) {
      try {
        const res = await client.callTool({ name: 'update_task_status', arguments: { task_id: taskId, status } })
        return res.isError ? { ok: false, message: text(res) } : { ok: true }
      } catch (err) {
        return { ok: false, message: message(err) }
      }
    },

    async verifyTaskAgainstPlan(taskId, worktreePath) {
      let res
      try {
        res = await client.callTool({ name: 'verify_task_against_plan', arguments: { task_id: taskId, worktree_path: worktreePath } })
      } catch (err) {
        return { ok: false, message: message(err) }
      }
      if (res.isError) return { ok: false, message: text(res) }
      const body = text(res)
      let parsed: unknown
      try {
        parsed = JSON.parse(body)
      } catch {
        return { ok: false, message: body }
      }
      const p = parsed as { result?: unknown; message?: unknown }
      const out: { ok: boolean; result?: PlanCheckResult; message?: string } = { ok: true }
      if (typeof p?.result === 'string' && ['aligned', 'partial', 'empty', 'divergent'].includes(p.result)) out.result = p.result
      if (typeof p?.message === 'string') out.message = p.message
      return out
    },

    async log(kind, args) {
      // Best-effort: a logging failure must never fail a job, only be reported.
      const name = kind === 'implementation' ? 'log_implementation' : kind === 'commit' ? 'log_commit' : 'log_test_result'
      const arguments: Record<string, unknown> = { story_id: args.storyId, task_id: args.taskId, content: args.content }
      if (kind === 'commit') {
        arguments.commit_hash = args.commitHash
        arguments.commit_message = args.commitMessage
      }
      if (kind === 'test') arguments.status = args.status
      try {
        await client.callTool({ name, arguments })
      } catch (err) {
        console.error(`[control] ${name} mislukt: ${message(err)}`)
      }
    },
  }
}"}

